// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.Receipt.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(receipt.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ReceiptUpsertBulk) UpdateNewValues() *ReceiptUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(receipt.FieldID)
			}
			if _, exists := b.mutation.UserID(); exists {
				s.SetIgnore(receipt.FieldUserID)
			}
			if _, exists := b.mutation.MutationID(); exists {
				s.SetIgnore(receipt.FieldMutationID)
			}
			if _, exists := b.mutation.RequestHash(); exists {
				s.SetIgnore(receipt.FieldRequestHash)
			}
			if _, exists := b.mutation.EntryRef(); exists {
				s.SetIgnore(receipt.FieldEntryRef)
			}
			if _, exists := b.mutation.MediaRef(); exists {
				s.SetIgnore(receipt.FieldMediaRef)
			}
			if _, exists := b.mutation.ResultRevision(); exists {
				s.SetIgnore(receipt.FieldResultRevision)
			}
			if _, exists := b.mutation.ResultState(); exists {
				s.SetIgnore(receipt.FieldResultState)
			}
			if _, exists := b.mutation.ResultSnapshot(); exists {
				s.SetIgnore(receipt.FieldResultSnapshot)
			}
			if _, exists := b.mutation.SnapshotVersion(); exists {
				s.SetIgnore(receipt.FieldSnapshotVersion)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(receipt.FieldCreatedAt)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.Receipt.Create().
